// src/index.ts
import { Plugin as PluginV2 } from "@opencode/plugin";
import { tool } from "@opencode-ai/plugin";

// src/auth.ts
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { xdgConfig, xdgData } from "xdg-basedir";
var DEFAULT_OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1";
var DEFAULT_OPENROUTER_MODEL = "xiaomi/mimo-v2.6-flash";
function normalizeOpenRouterBaseURL(raw) {
  const fallback = DEFAULT_OPENROUTER_BASE_URL;
  const value = raw?.trim() || fallback;
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error(`Invalid OpenRouter base URL: ${value}`);
  }
  url.search = "";
  url.hash = "";
  url.pathname = url.pathname.replace(/\/+$/, "");
  if (!url.pathname || url.pathname === "/") {
    url.pathname = "/api/v1";
  } else if (!url.pathname.endsWith("/api/v1") && !url.pathname.endsWith("/v1")) {
    url.pathname = `${url.pathname}/api/v1`;
  }
  return url.toString().replace(/\/+$/, "");
}
function resolveOpenRouterAuth(modelOverride, source) {
  const providerOptions = source ? source.providerOptions : loadOpenCodeConfig()?.provider?.openrouter?.options;
  const apiKey = readString(process.env.OPENROUTER_API_KEY) ?? extractApiKey(source ? source.credential : loadAuthData()?.openrouter) ?? readString(providerOptions?.apiKey);
  const model = readString(modelOverride) ?? readString(process.env.OPENROUTER_MODEL) ?? readString(providerOptions?.model) ?? DEFAULT_OPENROUTER_MODEL;
  const baseURL = normalizeOpenRouterBaseURL(readString(process.env.OPENROUTER_BASE_URL) ?? readString(providerOptions?.baseURL));
  if (!apiKey) {
    throw new Error("OpenRouter API key not found. Set OPENROUTER_API_KEY, connect OpenRouter in OpenCode, or configure the openrouter provider API key.");
  }
  return { apiKey, baseURL, model };
}
function loadAuthData() {
  const inline = process.env.OPENCODE_AUTH_CONTENT;
  if (inline?.trim()) {
    return parseJsonObject(inline, "OPENCODE_AUTH_CONTENT");
  }
  const authPath = xdgData ? join(xdgData, "opencode", "auth.json") : undefined;
  if (!authPath || !existsSync(authPath))
    return;
  return parseJsonObject(readFileSync(authPath, "utf8"), authPath);
}
function loadOpenCodeConfig() {
  if (!xdgConfig)
    return;
  for (const name of ["opencode.jsonc", "opencode.json"]) {
    const path = join(xdgConfig, "opencode", name);
    if (existsSync(path)) {
      return parseJsonObject(parseJsonc(readFileSync(path, "utf8")), path);
    }
  }
  return;
}
function parseJsonObject(content, source) {
  try {
    return JSON.parse(content);
  } catch (error) {
    throw new Error(`Failed to parse ${source}: ${error instanceof Error ? error.message : String(error)}`);
  }
}
function parseJsonc(raw) {
  return stripJsonComments(raw).replace(/,\s*([}\]])/g, "$1");
}
function extractApiKey(value) {
  if (!value || typeof value !== "object")
    return;
  const record = value;
  return readString(record.key) ?? readString(record.apiKey) ?? readString(record.access) ?? readString(record.token);
}
function readString(value) {
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}
function stripJsonComments(input) {
  let output = "";
  let inString = false;
  let quote = "";
  let escaped = false;
  for (let index = 0;index < input.length; index++) {
    const char = input[index];
    const next = input[index + 1];
    if (inString) {
      output += char;
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === quote) {
        inString = false;
      }
      continue;
    }
    if (char === '"' || char === "'") {
      inString = true;
      quote = char;
      output += char;
      continue;
    }
    if (char === "/" && next === "/") {
      while (index < input.length && input[index] !== `
`)
        index++;
      output += `
`;
      continue;
    }
    if (char === "/" && next === "*") {
      index += 2;
      while (index < input.length && !(input[index] === "*" && input[index + 1] === "/"))
        index++;
      index++;
      continue;
    }
    output += char;
  }
  return output;
}

// src/input-audio.ts
import { readFile } from "node:fs/promises";
import { extname, isAbsolute, resolve } from "node:path";
import { fileTypeFromBuffer } from "file-type";
var SUPPORTED_FORMATS = new Set(["wav", "mp3", "flac", "m4a", "ogg", "webm", "aac"]);
var MIME_TO_FORMAT = {
  "audio/aac": "aac",
  "audio/flac": "flac",
  "audio/m4a": "m4a",
  "audio/mp4": "m4a",
  "audio/mpeg": "mp3",
  "audio/ogg": "ogg",
  "audio/wav": "wav",
  "audio/wave": "wav",
  "audio/webm": "webm",
  "audio/x-flac": "flac",
  "audio/x-m4a": "m4a",
  "audio/x-wav": "wav"
};
var EXTENSION_TO_FORMAT = {
  ".aac": "aac",
  ".flac": "flac",
  ".m4a": "m4a",
  ".mp3": "mp3",
  ".ogg": "ogg",
  ".wav": "wav",
  ".webm": "webm"
};
var FORMAT_TO_MIME = {
  aac: "audio/aac",
  flac: "audio/flac",
  m4a: "audio/mp4",
  mp3: "audio/mpeg",
  ogg: "audio/ogg",
  wav: "audio/wav",
  webm: "audio/webm"
};
function resolveAudioPath(inputPath, directory) {
  const trimmed = inputPath.trim();
  if (!trimmed)
    throw new Error("Audio file path must not be empty");
  return isAbsolute(trimmed) ? resolve(trimmed) : resolve(directory, trimmed);
}
async function readInputAudio(inputPath, directory) {
  const path = resolveAudioPath(inputPath, directory);
  let buffer;
  try {
    buffer = Buffer.from(await readFile(path));
  } catch (error) {
    throw new Error(`Failed to read audio file ${path}: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (buffer.length === 0)
    throw new Error(`Audio file is empty: ${path}`);
  const detected = await fileTypeFromBuffer(buffer);
  const detectedFormat = detected ? MIME_TO_FORMAT[detected.mime] : undefined;
  const extensionFormat = EXTENSION_TO_FORMAT[extname(path).toLowerCase()];
  const format = detectedFormat ?? extensionFormat;
  if (!format || !SUPPORTED_FORMATS.has(format)) {
    const detectedLabel = detected ? `${detected.mime} (${detected.ext})` : "unknown type";
    throw new Error(`Unsupported audio file ${path}: ${detectedLabel}. Supported formats: ${[...SUPPORTED_FORMATS].join(", ")}`);
  }
  return {
    path,
    format,
    base64: buffer.toString("base64"),
    mime: detected?.mime ?? FORMAT_TO_MIME[format],
    size: buffer.length
  };
}
async function readInputAudios(paths, directory) {
  if (!Array.isArray(paths) || paths.length === 0)
    throw new Error("At least one audio file path is required");
  return Promise.all(paths.map((path) => readInputAudio(path, directory)));
}

// src/openrouter.ts
async function analyzeAudioWithOpenRouter(auth, prompt, audios, signal) {
  const body = {
    model: auth.model,
    ...auth.model.split(":")[0] === "xiaomi/mimo-v2.6-flash" && { reasoning: { enabled: false } },
    messages: [
      {
        role: "user",
        content: [
          { type: "text", text: prompt },
          ...audios.map((audio) => ({
            type: "input_audio",
            input_audio: {
              data: audio.base64,
              format: audio.format
            }
          }))
        ]
      }
    ]
  };
  let response;
  try {
    response = await fetch(`${auth.baseURL}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${auth.apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body),
      signal
    });
  } catch (error) {
    throw new Error(`OpenRouter request failed: ${error instanceof Error ? error.message : String(error)}`);
  }
  const responseText = await response.text();
  if (!response.ok) {
    throw new Error(`OpenRouter request failed with status ${response.status}: ${responseText.slice(0, 500)}`);
  }
  let json;
  try {
    json = JSON.parse(responseText);
  } catch (error) {
    throw new Error(`Failed to parse OpenRouter response JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  const choices = Array.isArray(json?.choices) ? json.choices : [];
  const failedChoice = choices.find((choice) => choice?.error || choice?.finish_reason === "error");
  const failed = json?.error || failedChoice;
  const answer = failed ? undefined : extractAnswer(choices);
  if (answer)
    return answer;
  const errorMessage = (json?.error ?? failedChoice?.error)?.message;
  const finishReason = (failedChoice ?? choices[0])?.finish_reason;
  const details = [
    `model=${auth.model}`,
    json?.provider && `provider=${json.provider}`,
    finishReason && `finish_reason=${finishReason}`,
    json?.id && `id=${json.id}`
  ].filter(Boolean).join(", ");
  const message = failed ? "OpenRouter completion failed" : "OpenRouter response did not contain a text answer";
  throw new Error(`${message} (${details})${typeof errorMessage === "string" ? `: ${errorMessage.slice(0, 500)}` : ""}`);
}
function extractAnswer(choices) {
  for (const choice of choices) {
    const content = choice?.message?.content;
    if (typeof content === "string" && content.trim())
      return content.trim();
    if (Array.isArray(content)) {
      const text = content.map((part) => part?.text).filter((value) => typeof value === "string" && value.trim().length > 0).join(`
`).trim();
      if (text)
        return text;
    }
  }
  return;
}

// src/index.ts
var DESCRIPTION = "Analyze, describe, compare, transcribe, or answer questions about one or more local audio files using OpenRouter audio-capable models.";
var FILES_DESCRIPTION = "Local audio file paths, relative to the project directory unless absolute.";
var PROMPT_DESCRIPTION = "Question or instruction for the audio files.";
var MODEL_DESCRIPTION = "Optional OpenRouter model override for this request.";
async function readAudio(args, directory, signal, source) {
  const prompt = args.prompt.trim();
  if (!prompt)
    throw new Error("Prompt must not be empty");
  signal.throwIfAborted();
  const auth = resolveOpenRouterAuth(args.model, source);
  const audios = await readInputAudios(args.files, directory);
  signal.throwIfAborted();
  const answer = await analyzeAudioWithOpenRouter(auth, prompt, audios, signal);
  return {
    output: answer,
    metadata: {
      provider: "openrouter",
      model: auth.model,
      files: audios.map(({ path, format, mime, size }) => ({ path, format, mime, size }))
    }
  };
}
var ReadAudioPlugin = async (_input) => {
  return {
    tool: {
      read_audio: tool({
        description: DESCRIPTION,
        args: {
          files: tool.schema.array(tool.schema.string()).min(1).describe(FILES_DESCRIPTION),
          prompt: tool.schema.string().describe(PROMPT_DESCRIPTION),
          model: tool.schema.string().optional().describe(MODEL_DESCRIPTION)
        },
        execute(args, ctx) {
          return readAudio(args, ctx.directory, ctx.abort);
        }
      })
    }
  };
};
var src_default = {
  ...PluginV2.define({
    id: "opencode-read-audio",
    async setup(ctx) {
      await ctx.tool.transform((editor) => {
        editor.add({
          name: "read_audio",
          description: DESCRIPTION,
          input: {
            type: "object",
            properties: {
              files: { type: "array", items: { type: "string" }, minItems: 1, description: FILES_DESCRIPTION },
              prompt: { type: "string", description: PROMPT_DESCRIPTION },
              model: { type: "string", description: MODEL_DESCRIPTION }
            },
            required: ["files", "prompt"],
            additionalProperties: false
          },
          async execute(input, context) {
            context.signal.throwIfAborted();
            const session = await ctx.session.get({ sessionID: context.sessionID });
            const providers = await ctx.provider.list({ location: session.location });
            const provider = providers.data.find((item) => item.id === "openrouter");
            const connection = process.env.OPENROUTER_API_KEY?.trim() ? undefined : await ctx.integration.connection.active(provider?.integrationID ?? "openrouter");
            const credential = connection ? await ctx.integration.connection.resolve(connection) : undefined;
            const result = await readAudio(input, session.location.directory, context.signal, {
              credential,
              providerOptions: provider?.settings
            });
            return { content: result.output, metadata: result.metadata };
          }
        });
      });
    }
  }),
  server: ReadAudioPlugin
};
export {
  src_default as default
};
